NO_BUKKIT='''import com.gonzotech.machines.network.*;import net.minecraft.server.level.*;import net.minecraft.core.*;public class NoBukkit{public static void main(String[] a){ServerLevel l=new ServerLevel();for(int i=0;i<100000;i++)if(WorldGuardFlags.decision(l,new BlockPos(0,0,0),WorldGuardFlags.Action.PLACE)!=null)throw new AssertionError("absent must not gate");if(l.reads!=0||l.chunkReads!=0)throw new AssertionError("absent region/chunk scans");WorldGuardFlags.stopped(new net.neoforged.neoforge.event.server.ServerStoppedEvent(l.server));System.out.println("PASS 100000 absent-API decisions, zero block/chunk reads");}}'''

def api_pins():
 flags=(FIX/'Flags.java.txt').read_text()
 for name,constructor,default in [('BUILD','BuildFlag','true'),('BLOCK_PLACE','StateFlag','false'),('BLOCK_BREAK','StateFlag','false'),('PISTONS','StateFlag','true')]:
  flag_id={'BUILD':'build','BLOCK_PLACE':'block-place','BLOCK_BREAK':'block-break','PISTONS':'pistons'}[name]
  assert f'{name} = register(new {constructor}("{flag_id}", {default})' in flags
 assert 'public static World adapt(org.bukkit.World world)' in (FIX/'BukkitAdapter.java.txt').read_text()
 assert 'public ServerLevel getHandle()' in (FIX/'CraftWorld.java.txt').read_text()
 assert 'RegionManager get(World world)' in (FIX/'RegionContainer.java.txt').read_text()
 assert 'getApplicableRegions(BlockVector3 position)' in (FIX/'RegionManager.java.txt').read_text()

def sources(overrides=None,legacy=False):
 text=overrides.get('BE',work.SOURCE.read_text()) if overrides else work.SOURCE.read_text();src=work.files(text=text);src.update(STUBS)
 helpers=work.HELPERS.replace('boolean mayTouchBreak(ServerLevel s,BlockPos p){return !denied.contains(p);}boolean mayTouchPlace(ServerLevel s,BlockPos p){return !denied.contains(p);}','')
 probe=src['WorkProbe.java'].replace(work.HELPERS,helpers).split('static int checks;',1)[0]
 # Reuse exactly the work harness' production methods/fields, but replace boundary permission stubs.
 probe+='\n'+ '\n'.join(method(text,n) for n in ('private boolean mayTouchPlace(', 'private boolean mayTouchBreak(', 'private boolean touchCached(', 'private void digStep('))+'\n'+EXTRA+'\n}'
 probe='import java.nio.file.Path;import net.neoforged.neoforge.common.util.BlockSnapshot;import net.neoforged.neoforge.event.level.BlockEvent;import net.neoforged.neoforge.common.NeoForge;\n'+probe
 src['WorkProbe.java']=probe
 src['PluginTests.java']=PLUGIN_TEST
 src['NoBukkit.java']=NO_BUKKIT if not legacy else NO_BUKKIT.replace('WorldGuardFlags.stopped(new net.neoforged.neoforge.event.server.ServerStoppedEvent(l.server));','')
 # Old revision helper's stop callback accepts the event but doesn't inspect its API.
 for item in json.loads((FIX/'manifest.json').read_text())['files']:
  data=(FIX/item['file']).read_bytes();assert len(data)==item['bytes'] and hashlib.sha256(data).hexdigest()==item['sha256'],item['file']
  if item['repository']=='truegonzodev/gonzotech':assert subprocess.check_output(['git','show',item['commit']+':'+item['source']],cwd=ROOT)==data
  if item['executable']:src[item['source'].split('src/main/java/')[1]]=data.decode()
 for name in ('WorldGuardFlags','BukkitWorldGuardAdapter','PlotnickRegionPolicy'):src[NET+name+'.java']=(JAVA/(NET+name+'.java')).read_text()
 if legacy:src[NET+'WorldGuardFlags.java']=(FIX/'WorldGuardFlags-331.java.txt').read_text()
 if overrides:src.update({k:v for k,v in overrides.items() if k!='BE'})
 return src

def run(overrides=None,legacy=False):
 with tempfile.TemporaryDirectory() as tmp:
  d=Path(tmp);out=d/'classes';plugins=d/'plugins';paths=[]
  for path,text in sources(overrides,legacy).items():
   p=d/'src'/path;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(text);paths.append(str(p))
  ecj=os.environ.get('ECJ_JAR');home=Path(os.environ.get('JAVA_HOME','/usr'));java=str(home/'bin/java')
  cmd=[java,'-jar',ecj,'-21','-proc:none','-nowarn','-d',str(out)] if ecj else ['javac','--release','21','-d',str(out)]
  result=subprocess.run(cmd+paths,text=True,capture_output=True);assert result.returncode==0,'COMPILE ERROR\n'+result.stdout+result.stderr
  # API classes and real WG engine exist ONLY in the plugin loader, never the mod loader.
  plugins.mkdir()
  for path in list((out/'com/sk89q').rglob('*.class'))+list(out.glob('Plugin*.class')):
   dest=plugins/path.relative_to(out);dest.parent.mkdir(parents=True,exist_ok=True);shutil.move(path,dest)
  result=subprocess.run([java,'-cp',str(out),'WorkProbe',str(plugins)],text=True,capture_output=True)
  if result.returncode==0 and not legacy:
   (out/'org/bukkit/Bukkit.class').unlink()
   absent=subprocess.run([java,'-cp',str(out),'NoBukkit'],text=True,capture_output=True)
   if absent.returncode:return absent
   result.stdout+=absent.stdout
  return result

if __name__=='__main__':
 api_pins()
 result=run();assert result.returncode==0,result.stdout+result.stderr;print(result.stdout,end='')
