 result=run({'BE':be.replace('if (!mayTouchBreak(server, pos)) { pending = true; continue; }', '')});assert result.returncode!=0 and 'AssertionError' in result.stderr,'ore suction bypass survived';print('REJECTED: side ore suction permission bypass')
 result=run(legacy=True);assert result.returncode!=0 and 'AssertionError' in result.stderr,'exact331 survived';print('REJECTED: exact 331 WG implementation (compiled, assertion failure)')
